SELECT CD_ID, CD_NM, CD_CN, USE_YN FROM CMMN_CD_MST
AND USE_YN = #{useYn}
ORDER BY CD_ID

SELECT CD_ID, CD_NM, CD_CN, USE_YN
FROM CMMN_CD_MST
WHERE CD_ID = #{cdId}

SELECT CD_ID, CD_DTL_ID, CD_DTL_NM, CD_DTL_CN, SORT_SEQ, USE_YN, ETC1, ETC2, ETC3, ATCH_FILE_MNG_NO, REG_DT, RGTR
FROM CMMN_CD_DTL


		AND CD_ID = #{cdId}


		AND USE_YN = #{useYn}


ORDER BY SORT_SEQ, CD_DTL_ID

SELECT CD_ID, CD_DTL_ID, CD_DTL_NM, CD_DTL_CN, SORT_SEQ, USE_YN, ETC1, ETC2, ETC3, ATCH_FILE_MNG_NO, REG_DT, RGTR
FROM CMMN_CD_DTL
WHERE CD_ID = #{cdId} AND CD_DTL_ID = #{cdDtlId}

